import {incrementalRecord} from './incremental-registry.js';
import {annualTextHTML} from './annual-localization.js';
import {displayNumber,precisionInputAttributes,readPrecisionInput,bindPrecisionInput} from './number-display.js';
import {RMBS_MESSAGES} from './rmbs-messages.js';
export {RMBS_MESSAGES} from './rmbs-messages.js';
const a=k=>annualTextHTML(RMBS_MESSAGES[k][0]),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),n=x=>displayNumber(x,2);
const policyScalarKeys=['baseline_total_sbc_pct_revenue','reported_unit_vesting_fraction','withholding_fraction','residual_claim_cash_fraction','marketable_securities_liquidity_haircut','reported_units_already_in_common_m','residual_legacy_share_equivalents_m'];
const policyCell=v=>v===null||typeof v==='number';
const editablePolicy=p=>p&&typeof p==='object'&&!Array.isArray(p)&&policyScalarKeys.every(k=>Object.hasOwn(p,k)&&policyCell(p[k]))&&['legacy_expense_runout_m','vesting_weights'].every(k=>Array.isArray(p[k])&&p[k].length===10&&p[k].every(policyCell));
export function rmbsPolicyEditorHTML(d){
 if(d?.ticker!=='RMBS')return '';const r=incrementalRecord('RMBS'),p=d.rmbsAwardPolicy;
 const input=(key,value,index)=>`<label>${a(key)}${index===undefined?'':` · ${index+1}`}<input type="text" inputmode="decimal" data-rmbs-policy="${key}" ${index===undefined?'':`data-rmbs-index="${index}"`} ${precisionInputAttributes(value)} aria-describedby="rmbs-policy-help"></label>`;
 return `<section class="research-card" id="rmbs-policy-tool"><h3>${a('title')}</h3><p>${a(p===null?'none':'selected')}</p><div class="result-actions">${r.awardExamples.map((e,i)=>`<button type="button" class="quiet" data-rmbs-example="${i}">${a(['zero','small','large'][i])}</button>`).join('')}<button type="button" class="quiet" data-rmbs-clear>${a('clear')}</button></div><div id="rmbs-policy-help">${['scope','awards','claims','tax','funding','wacc'].map(k=>`<p>${annualTextHTML(r.prose[k].en)}</p>`).join('')}</div>${p!==null&&!editablePolicy(p)?`<p class="research-warning">${a('error')}</p>`:''}${editablePolicy(p)?`<div class="research-field-grid">${['baseline_total_sbc_pct_revenue','reported_unit_vesting_fraction','withholding_fraction','residual_claim_cash_fraction','marketable_securities_liquidity_haircut','reported_units_already_in_common_m','residual_legacy_share_equivalents_m'].map(k=>input(k,p[k])).join('')}</div><details><summary>${a('legacy_expense_runout_m')} / ${a('vesting_weights')}</summary><div class="research-field-grid">${['legacy_expense_runout_m','vesting_weights'].flatMap(k=>Array.from({length:10},(_,i)=>input(k,p[k]?.[i],i))).join('')}</div></details>`:''}</section>`;
}
export function bindRmbsPolicy(root,d,{save,rerender,updateResults,remember,endEdit}={}){
 if(d?.ticker!=='RMBS')return;
 root.querySelectorAll('[data-rmbs-example]').forEach(el=>el.onclick=()=>{const focus=el.ownerDocument?.activeElement===el;remember?.('rmbs-policy-select');d.rmbsAwardPolicy=structuredClone(incrementalRecord('RMBS').awardExamples[Number(el.dataset.rmbsExample)].selection);save();rerender();endEdit?.();if(focus)root.querySelector(`[data-rmbs-example="${el.dataset.rmbsExample}"]`)?.focus({preventScroll:true});});
 const clear=root.querySelector('[data-rmbs-clear]');if(clear)clear.onclick=()=>{remember?.('rmbs-policy-clear');d.rmbsAwardPolicy=null;save();rerender();endEdit?.();root.querySelector('[data-rmbs-clear]')?.focus({preventScroll:true});};
 if(!editablePolicy(d.rmbsAwardPolicy))return;
 root.querySelectorAll('[data-rmbs-policy]').forEach(el=>{el.onfocus=()=>endEdit?.();el.onblur=()=>endEdit?.();el.oninput=()=>{const k=el.dataset.rmbsPolicy;remember?.('rmbs:'+k+':'+(el.dataset.rmbsIndex??''));const value=el.value.trim()===''?null:readPrecisionInput(el);if(el.dataset.rmbsIndex!==undefined)d.rmbsAwardPolicy[k][Number(el.dataset.rmbsIndex)]=value;else d.rmbsAwardPolicy[k]=value;save();updateResults();};bindPrecisionInput(el);});
}
export function rmbsAllocationHTML(b){if(b?.ticker!=='RMBS')return '';const v=b.rmbsAllocation;if(v.status==='AWARD_POLICY_SELECTION_REQUIRED')return `<p>${a('none')}</p>`;return `<div class="research-card"><p>${a('selected')}</p><p>${a('reconciliation')}: ${n(v.ordinary_equity_allocation)} + ${n(v.legacy_net_equity_allocation)} + ${n(v.legacy_cash_settlement_pv)} = ${n(v.equity_pool_before_legacy_claims)} USDm</p><p>${a('initial')}: ${n(v.initial_liquidity_after_reserves)} USDm</p>${v.external_funding_required>0?`<p class="error">${a('shortfall')}: ${n(v.external_funding_required)} USDm</p>`:''}</div>`;}
export function rmbsFundingHTML(r){const v=r.rmbsAllocation;if(!v)return '';if(v.status==='AWARD_POLICY_SELECTION_REQUIRED')return `<p>${a('none')}</p>`;const cols=['Year','Legacy after-tax expense removed','Remaining new-grant cash-equivalent cost','Gross legacy cash settlement','Cash after legacy settlement before receipts','Closing cash after reserves'];return `<h3>${a('funding')}</h3><p>${annualTextHTML(incrementalRecord('RMBS').prose.funding.en)}</p><div class="research-table-scroll"><table class="research-table"><caption>${a('funding')} · USDm</caption><thead><tr>${cols.map(c=>`<th scope="col">${annualTextHTML(c)}</th>`).join('')}</tr></thead><tbody>${v.rows.map(row=>`<tr><th scope="row">${esc(row.period_end)}</th>${['legacy_after_tax_addback','remaining_new_grant_cash_equivalent_cost','legacy_withholding_cash','cash_after_withholding_before_receipts','closing_cash_after_reserves'].map(k=>`<td>${n(row[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
